import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;

public class TextRed {
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            int size = Integer.parseInt(br.readLine());
            String line = br.readLine();
            br.close();

            int maxSegment = 0;
            int segmentLength = 0;
            boolean insideParentheses = false;
            ArrayList<Integer> maxSegments = new ArrayList<>();
            maxSegments.add(0);
            char[] chArray = line.toCharArray();

            for (char ch : chArray) {
                if (ch == '(') {
                    insideParentheses = true;
                    if (segmentLength != 0) {
                        maxSegments.add(segmentLength);
                    }
                    segmentLength = 0;
                } else if (ch == ')') {
                    insideParentheses = false;
                } else if (!insideParentheses && ch != '_') {
                    segmentLength++;
                } else if (!insideParentheses && ch == '_') {
                    maxSegments.add(segmentLength);
                    segmentLength = 0;
                }
            }
            if (segmentLength != 0) {
                maxSegments.add(segmentLength);
            }

            System.out.print(Collections.max(maxSegments) + " ");

            int verbCount = 0;
            int countInBrackets = 0;
            boolean inBrackets = false;
            for (char ch : chArray) {
                if (ch == '(') {
                    inBrackets = true;
                    countInBrackets = 0;
                } else if (ch == ')') {
                    inBrackets = false;
                    if (countInBrackets != 0) {
                        verbCount++;
                    }
                } else if (inBrackets && ch != '_') {
                    countInBrackets++;
                } else if (inBrackets && ch == '_') {
                    if (countInBrackets != 0) {
                        verbCount++;
                    }
                    countInBrackets = 0;
                }
            }

            System.out.print(verbCount);
        } catch (Exception e) {
            System.out.println(0 + " " + 0);
        }
    }
}
